 let progress=trash.filter(a=>a.got).length/12;ctx.globalAlpha=.35+progress*.65;for(const f of flowers){let wave=Math.sin(t*.0016+f.phase)*.9;ctx.strokeStyle='#609653';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(f.x,f.y+5);ctx.quadraticCurveTo(f.x+wave,f.y+2,f.x+wave*1.3,f.y-2);ctx.stroke();ctx.fillStyle=f.c;for(let j=0;j<4;j++){let a=j*Math.PI/2;ctx.beginPath();ctx.ellipse(f.x+wave*1.3+Math.cos(a)*2,f.y-2+Math.sin(a)*2,1.5*f.s,1*f.s,a,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#efcf69';ctx.beginPath();ctx.arc(f.x+wave*1.3,f.y-2,1.2,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
