function drawTree(x,y,r,t){ctx.save();ctx.fillStyle='#6a8c5140';ctx.beginPath();ctx.ellipse(x+7,y+r*.7,r*.9,r*.35,0,0,7);ctx.fill();rounded(x-6,y-1,12,r*.68,4,'#886344');ctx.fillStyle='#789e5c';ctx.beginPath();ctx.arc(x,y-r*.2,r,0,7);ctx.fill();ctx.fillStyle='#85aa67';ctx.beginPath();ctx.arc(x-r*.43,y-r*.08,r*.58,0,7);ctx.arc(x+r*.36,y-r*.1,r*.61,0,7);ctx.fill();ctx.fillStyle='#9bbd74';ctx.beginPath();ctx.arc(x-r*.15,y-r*.61,r*.51,0,7);ctx.fill();ctx.globalAlpha=.24;ctx.fillStyle='#e5f1c2';ctx.beginPath();ctx.arc(x-r*.25,y-r*.47,r*.3,0,7);ctx.fill();ctx.restore()}
