function draw(t){drawBackground(t);for(const a of trash)drawTrash(a,t);drawPlayer()}
function playTone(freq=610){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),gain=audio.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*1.55,audio.currentTime+.12);gain.gain.setValueAtTime(.08,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);o.connect(gain);gain.connect(audio.destination);o.start();o.stop(audio.currentTime+.19)}catch(e){}}
function reset(){player.x=490;player.y=326;player.walk=0;trash=initialTrash.map((t,i)=>({...t,id:i,got:false,phase:i*1.7}));collectedEl.textContent='0';meter.style.width='0%';mood.textContent='A little wild';document.getElementById('worldLabel').innerHTML='🍃 &nbsp;Meadow park';running=true;won=false;document.getElementById('intro').classList.add('hidden');document.getElementById('ending').classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}
function update(dt){let dx=0,dy=0;if(keys.has('ArrowLeft')||keys.has('a')||keys.has('A')||held.has('left'))dx--;if(keys.has('ArrowRight')||keys.has('d')||keys.has('D')||held.has('right'))dx++;if(keys.has('ArrowUp')||keys.has('w')||keys.has('W')||held.has('up'))dy--;if(keys.has('ArrowDown')||keys.has('s')||keys.has('S')||held.has('down'))dy++;let len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.x=Math.max(26,Math.min(W-26,player.x+dx*190*dt));player.y=Math.max(47,Math.min(H-23,player.y+dy*190*dt));player.walk+=dt*13}else player.walk*=.8;
 for(const a of trash){if(!a.got&&Math.hypot(player.x-a.x,player.y-a.y)<26){a.got=true;let n=trash.filter(x=>x.got).length;collectedEl.textContent=n;meter.style.width=(n/12*100)+'%';playTone(540+n*15);message.innerHTML=n===12?'<strong>Every last bit!</strong> Look how the meadow glows.':`<strong>Lovely work!</strong> ${12-n} little ${12-n===1?'bit':'bits'} left to find.`;if(n===4){mood.textContent='Getting brighter';document.getElementById('worldLabel').innerHTML='🌱 &nbsp;Growing greener'}if(n===8){mood.textContent='Looking lovely';document.getElementById('worldLabel').innerHTML='🌼 &nbsp;Blooming meadow'}if(n===12){mood.textContent='Thriving!';document.getElementById('worldLabel').innerHTML='🦋 &nbsp;Meadow in bloom';won=true;running=false;setTimeout(()=>document.getElementById('ending').classList.remove('hidden'),700)}}}}
function loop(now){if(!running)return;let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw(now);if(running)requestAnimationFrame(loop)}
document.getElementById('startBtn').addEventListener('click',()=>{playTone(440);reset()});document.getElementById('againBtn').addEventListener('click',()=>{playTone(440);reset()});document.getElementById('soundBtn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';if(soundOn)playTone(640)});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key);if(!running&&e.key==='Enter'&&!won)reset()},{passive:false});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());document.querySelectorAll('.mobile-controls button').forEach(btn=>{const dir=btn.dataset.dir;btn.addEventListener('pointerdown',e=>{e.preventDefault();held.add(dir);btn.classList.add('held');btn.setPointerCapture(e.pointerId)});const release=e=>{e.preventDefault();held.delete(dir);btn.classList.remove('held')};btn.addEventListener('pointerup',release);btn.addEventListener('pointercancel',release);btn.addEventListener('lostpointercapture',release)});
new ResizeObserver(()=>{let dpr=Math.min(window.devicePixelRatio||1,2),rect=canvas.getBoundingClientRect();if(!rect.width)return;canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);draw(performance.now())}).observe(canvas);draw(performance.now());
})();
</script></body></html>

