  for(const a of trash){if(!a.got&&Math.hypot(player.x-a.x,player.y-a.y)<26){a.got=true;let n=trash.filter(x=>x.got).length;collectedEl.textContent=n;meter.style.width=(n/12*100)+'%';playTone(540+n*15);message.innerHTML=n===12?'<strong>Every last bit!</strong> Look how the meadow glows.':`<strong>Lovely work!</strong> ${12-n} little ${12-n===1?'bit':'bits'} left to find.`;if(n===4){mood.textContent='Getting brighter';document.getElementById('worldLabel').innerHTML='🌱 &nbsp;Growing greener'}if(n===8){mood.textContent='Looking lovely';document.getElementById('worldLabel').innerHTML='🌼 &nbsp;Blooming meadow'}if(n===12){mood.textContent='Thriving!';document.getElementById('worldLabel').innerHTML='🦋 &nbsp;Meadow in bloom';won=true;running=false;setTimeout(()=>document.getElementById('ending').classList.remove('hidden'),700)}}}}
 function loop(now){if(!running)return;let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw(now);if(running)requestAnimationFrame(loop)}
 document.getElementById('startBtn').addEventListener('click',()=>{playTone(440);reset()});document.getElementById('againBtn').addEventListener('click',()=>{playTone(440);reset()});document.getElementById('soundBtn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';if(soundOn)playTone(640)});

